import { useState, useEffect } from 'react';
import SearchResults from '../SearchResults/searchresult';
import Song from '../Song/song';
import useFetch from '../../hooks/useFetch';
import { useSelector, useDispatch } from 'react-redux';
import { removeSong } from '../../redux/libraryActions';
import { MainContent, LibraryContainer, Cargando, ProblemaAlCargar, BotonReinternat, BotonEliminar } from './styles';

function MusicLibraryMain({ url }) {
  const [trackUrl, setTrackUrl] = useState('');
  const { data, loading, error } = useFetch(url);
  const { data: trackData, loading: loadingTracks } = useFetch(trackUrl);

  const biblioteca = useSelector((state) => state);
  const dispatch = useDispatch();

  useEffect(() => {
    if (data?.album && data.album.length > 0) {
      const primerAlbum = data.album[0];
      setTrackUrl(`https://theaudiodb.com/api/v1/json/2/track.php?m=${primerAlbum.idAlbum}`);
    }
  }, [data]);

  const canciones = trackData?.track
    ? trackData.track.map((track) => ({
        id: track.idTrack,
        albumId: track.idAlbum,
        titulo: track.strTrack,
        artista: track.strArtist,
        album: track.strAlbum,
        duracion: track.intDuration && track.intDuration > 0
          ? `${Math.floor(track.intDuration / 60000)}:${String(
              Math.floor((track.intDuration % 60000) / 1000)
            ).padStart(2, '0')}`
          : '—',
      }))
    : [];

  return (
    <MainContent>
      {(loading || loadingTracks) && <Cargando>Cargando...</Cargando>}
      {error && (
        <div>
          <ProblemaAlCargar>Hubo un problema al cargar los datos.</ProblemaAlCargar>
          <BotonReinternat onClick={() => window.location.reload()}>Reintentar</BotonReinternat>
        </div>
      )}

      {!loading && !loadingTracks && !error && canciones.length > 0 && (
        <SearchResults canciones={canciones} />
      )}

      <hr />

      <LibraryContainer>
        <h2>Mis Favoritos</h2>
        {biblioteca.length === 0 ? (
          <p>Aún no has agregado canciones.</p>
        ) : (
          biblioteca.map((cancion) => (
            <div key={cancion.id} style={{ display: 'flex', alignItems: 'center' }}>
              <Song cancion={cancion} isLibrary={true} />

              <BotonEliminar onClick={() => dispatch(removeSong(cancion.id))}>Eliminar</BotonEliminar>
            </div>
          ))
        )}
      </LibraryContainer>
    </MainContent>
  );
}

export default MusicLibraryMain;
